class Utils {
  static convertValueByType = (value, type) => {
    switch (type) {
      case 'num': {
        const num = Number(value)
        return Number.isNaN(num) ? value : num
      }

      case 'bool':
        return value === 'true' || value === true

      case 'string':
      default:
        return String(value)
    }
  }

  static convertMap = (data, actionName, idName) => {
    const {
      action,
      identifer,
      ...rest
    } = data

    return {
      [actionName]: action,
      [idName]: identifer,
      ...rest
    }
  }
}

export default Utils;
