import ActionHistory from './page/ActionHistory'
import DynamicJs2Native from './page/DynamicJs2Native'
import './App.css';
import {
  HashRouter,
  Routes,
  Route
} from 'react-router-dom'

function App() {
  return (
    <HashRouter>
      <Routes>
        <Route
          path="/"
          element={<DynamicJs2Native />}
        />

        <Route
          path="/action-history"
          element={<ActionHistory />}
        />
      </Routes>
    </HashRouter>
  );
}

export default App;
