import '../css/DynamicJs2Native.css'
import React, { useEffect, useState } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import AlertModal from '../component/AlertModal'
import FileSelector from '../component/FileSelector'
import MemUtil from '../utils/MemUtil'
import StorageUtil from '../utils/StorageUtil'
import Utils from '../utils/Utils'

function DynamicJs2Native() {

  const DEFAULT_PARAM = {
    key: '',
    value: '',
    type: 'string'
  }

  const navigate = useNavigate()
  const location = useLocation()

  const [bridgeName, setBridgeName] = useState(StorageUtil.getStorage('bridgeName'))
  const [functionName, setFunctionName] = useState(StorageUtil.getStorage('functionName') ?? 'postMessage')
  const [actionName, setActionName] = useState(StorageUtil.getStorage('actionName') ?? 'action')
  const [idName, setIdName] = useState(StorageUtil.getStorage('idName') ?? 'identifer')
  const [alertMsg, setAlertMsg] = useState('')

  // 状态定义
  const [dataObjects, setDataObjects] = useState(() => {
    const draft = MemUtil.getDraft()
    return draft?.length > 0
      ? draft
      : [{
        action: '',
        params: [{ ...DEFAULT_PARAM }],
        result: null
      }]
  })

  useEffect(() => {
    MemUtil.saveDraft(dataObjects)
  }, [dataObjects])

  // 添加新的数据对象
  const addDataObject = (data) => {
    const newData = data ?? {
      action: '',
      params: [{ ...DEFAULT_PARAM }],
      result: null
    }
    setDataObjects([newData, ...dataObjects])
  }

  // 删除数据对象
  const removeDataObject = (index) => {
    const newDataObjects = [...dataObjects]
    newDataObjects.splice(index, 1)
    setDataObjects(newDataObjects)
  }

  // 更新action
  const updateAction = (index, value) => {
    const newDataObjects = [...dataObjects]
    newDataObjects[index].action = value
    setDataObjects(newDataObjects)
  }

  // 添加参数到特定数据对象
  const addParam = (dataObjIndex) => {
    const newDataObjects = [...dataObjects]
    newDataObjects[dataObjIndex].params.push({ ...DEFAULT_PARAM })
    setDataObjects(newDataObjects)
  }

  // 删除参数
  const removeParam = (dataObjIndex, paramIndex) => {
    const newDataObjects = [...dataObjects]
    newDataObjects[dataObjIndex].params.splice(paramIndex, 1)
    setDataObjects(newDataObjects)
  }

  // 更新参数
  const updateParam = (dataObjIndex, paramIndex, field, value) => {
    const newDataObjects = [...dataObjects]
    newDataObjects[dataObjIndex].params[paramIndex][field] = value
    setDataObjects(newDataObjects)
  }

  // 为单个数据对象生成数据
  const assembleSingleData = (dataObjIndex) => {

    const errorMsgList = []
    if (bridgeName == null || bridgeName === '') {
      errorMsgList.push('Bridge name')
    }

    if (functionName == null || functionName === '') {
      errorMsgList.push('Function name')
    }

    if (actionName == null || actionName === '') {
      errorMsgList.push('Action name')
    }

    if (idName == null || idName === '') {
      errorMsgList.push('Id name')
    }

    if (errorMsgList.length >0){
      setAlertMsg(`Please enter:             \n\n${errorMsgList.join('，')}`)
      return
    }

    const dataObj = dataObjects[dataObjIndex]

    if (dataObj.action === '') {
      setAlertMsg('Error:\nPlease enter action name!')
      return
    }

    if (window[bridgeName] == null) {
      setAlertMsg('Error:\nCheck your native bridge name')
      return
    }

    if (window[bridgeName]?.[functionName] == null) {
      setAlertMsg('Error:\nCheck your native function name')
      return
    }

    StorageUtil.setStorage('bridgeName', bridgeName)
    StorageUtil.setStorage('functionName', functionName)
    StorageUtil.setStorage('actionName', actionName)
    StorageUtil.setStorage('idName', idName)

    // 过滤掉空键的参数
    const validParams = dataObj.params.filter(param => param.key.trim() !== '')

    // 将参数数组转换为对象
    const paramsObj = {}
    validParams.forEach(param => {
      paramsObj[param.key] = Utils.convertValueByType(
        param.value,
        param.type
      )
    })

    // 组装最终数据
    const data = {
      action: dataObj.action,
      identifer: dataObj.action,
      params: paramsObj
    }
    StorageUtil.saveActionHistory(data)

    const displayData = {
      bridgeName: bridgeName,
      functionName: functionName,
      data: Utils.convertMap(data, actionName, idName)
    }

    // 更新该对象的结果
    const newDataObjects = [...dataObjects]
    newDataObjects[dataObjIndex].result = displayData
    setDataObjects(newDataObjects)

    // 调用原生方法
    window[bridgeName]?.[functionName]?.(JSON.stringify(Utils.convertMap(data, actionName, idName)))
  }

  window.callWeb = function (result) {
    // const {
    //   identifer,
    //   status,
    //   data,
    //   errorMessage
    // } = result
    setAlertMsg(JSON.stringify(result, null, 2))
  }

  useEffect(() => {
    const selectedAction = location.state

    if (!selectedAction) return

    const historyData = {
      action: selectedAction.action,
      params: Object.entries(
        selectedAction.params ?? {}
      )
        .map(([key, value]) => ({
          key,
          value: String(value),
          type:
            typeof value === 'number'
              ? 'num'
              : typeof value === 'boolean'
                ? 'bool'
                : 'string'
        })),
      result: null
    }

    setDataObjects(prev => {
      const hasOnlyEmptyItem =
        prev.length === 1 &&
        prev[0].action === ''

      if (hasOnlyEmptyItem || prev.length === 0) {
        return [historyData]
      }

      return [
        historyData,
        ...prev
      ]
    })
  }, [location.state])

  return (
    <div className="App-Content">

      <FileSelector/>
      <div className={'divider'}/>

      <div className="row">
        <input
          className="param-input"
          style={{ marginRight: 0 }}
          type="text"
          id="bridgeName"
          value={bridgeName}
          onChange={(e) => setBridgeName(e.target.value)}
          placeholder="请输入Bridge名称"
        />
        <input
          className="param-input"
          style={{ marginRight: 0 }}
          type="text"
          id="functionName"
          value={functionName}
          onChange={(e) => setFunctionName(e.target.value)}
          placeholder="请输入方法名称"
        />
      </div>

      <div className="row">
        <input
          className="param-input"
          style={{ marginRight: 0 }}
          type="text"
          id="actionName"
          value={actionName}
          onChange={(e) => setActionName(e.target.value)}
          placeholder="请输入Action名称"
        />
        <input
          className="param-input"
          style={{ marginRight: 0 }}
          type="text"
          id="idName"
          value={idName}
          onChange={(e) => setIdName(e.target.value)}
          placeholder="请输入id名称"
        />
      </div>

      <div className={'divider'}/>

      <div className={'row'}>
        <button
          type="button"
          className={'flex-button'}
          onClick={() => addDataObject()}
        >
          + 新增Action
        </button>

        <button
          type="button"
          className={'flex-button'}
          onClick={() =>
            navigate('/action-history')
          }
        >
          历史记录
        </button>
      </div>

      <div className={'divider-dash params-section'}/>

      <div>
        {dataObjects.map((dataObj, dataObjIndex) => (
          <div key={dataObj.id} className="action-card">
            <div style={{
              display: 'flex',
              justifyContent: 'flex-end'
            }}>
              <button
                className="remove-param-btn"
                onClick={() => removeDataObject(dataObjIndex)}
              >
                删除 Action
              </button>
            </div>

            <div className="form-group-center">
              <label htmlFor={`action-${dataObjIndex}`}>Action</label>
              <input
                type="text"
                id={`action-${dataObjIndex}`}
                value={dataObj.action}
                onChange={(e) => updateAction(dataObjIndex, e.target.value)}
                placeholder="请输入action"
              />
            </div>

            <div>
              <div className="params-header">
                <label>Params (参数)</label>
                <button className="add-param-btn" onClick={() => addParam(dataObjIndex)}>
                  + 添加参数
                </button>
              </div>

              {dataObj.params.map((param, paramIndex) => (
                <div key={paramIndex} className="param-item">
                  <input
                    type="text"
                    className="param-input"
                    value={param.key}
                    onChange={(e) => updateParam(dataObjIndex, paramIndex, 'key', e.target.value)}
                    placeholder="参数名"
                  />
                  {
                    param.type === 'bool' ? (
                      <select
                        className="param-input"
                        style={{
                          marginRight: '0px',
                          padding: '9pt 0',
                          borderRadius: '6px'
                        }}
                        value={param.value}
                        onChange={(e) =>
                          updateParam(dataObjIndex, paramIndex, 'value', e.target.value)
                        }
                      >
                        <option value="true">true</option>
                        <option value="false">false</option>
                      </select>
                    ) : (
                      <input
                        type="text"
                        className="param-input"
                        style={{ marginRight: '0px' }}
                        value={param.value}
                        onChange={(e) =>
                          updateParam(dataObjIndex, paramIndex, 'value', e.target.value)
                        }
                        placeholder="参数值"
                      />
                    )
                  }
                  <select
                    className="param-type-select"
                    style={{
                      padding: '9pt 0',
                      borderRadius: '6px'
                    }}
                    value={param.type}
                    onChange={(e) =>
                      updateParam(
                        dataObjIndex,
                        paramIndex,
                        'type',
                        e.target.value
                      )
                    }
                  >
                    <option value="string">Str</option>
                    <option value="num">Num</option>
                    <option value="bool">Bool</option>
                  </select>
                  <button
                    className="remove-param-btn"
                    onClick={() => removeParam(dataObjIndex, paramIndex)}
                  >
                    删除
                  </button>
                </div>
              ))}
            </div>

            {/* 单个对象的生成按钮 */}
            <button
              className="submit-btn"
              onClick={() => assembleSingleData(dataObjIndex)}
            >
              生成此数据对象并调用
            </button>

            {/* 单个对象的结果展示 */}
            {dataObj.result && (
              <div className="result-section">
                <div className="result-title">Action: {dataObj.action}:</div>
                <pre>{JSON.stringify(dataObj.result, null, 2)}</pre>
              </div>
            )}

            {dataObjIndex < dataObjects.length - 1 && <div className="divider-dash"/>}
          </div>
        ))}
      </div>

      <AlertModal
        alertMsg={alertMsg}
        onRequestClose={() => setAlertMsg('')}
      />
    </div>
  )
}

export default DynamicJs2Native

