const ACTION_HISTORY_KEY = 'ACTION_HISTORY'

class StorageUtil {

  static getStorage = key => {
    return localStorage.getItem(key)
  }

  static setStorage = (key, value) => {
    localStorage.setItem(key, value)
  }

  static getActionHistory = () => {
    try {
      return JSON.parse(
        localStorage.getItem(ACTION_HISTORY_KEY) ?? '[]'
      )
    } catch {
      return []
    }
  }

  static saveActionHistory = (data) => {
    const history = this.getActionHistory()

    const filtered = history.filter(
      item => item.action !== data.action
    )

    const newHistory = [
      {
        ...data,
        updatedAt: Date.now()
      },
      ...filtered
    ]

    localStorage.setItem(
      ACTION_HISTORY_KEY,
      JSON.stringify(newHistory)
    )
  }

  static removeActionHistory = (action) => {
    const history = this.getActionHistory()

    localStorage.setItem(
      ACTION_HISTORY_KEY,
      JSON.stringify(
        history.filter(item => item.action !== action)
      )
    )
  }
}

export default StorageUtil

