import React, { useState } from 'react'
import Modal from 'react-modal'

function AlertModal(props) {
  const [isCopied, setIsCopied] = useState(false)
  const copyToClipboard = async (text) => {
    try {
      await navigator.clipboard.writeText(text)
      setIsCopied(true)
      setTimeout(() => setIsCopied(false), 2000)
    } catch (err) {
      // 降级方案
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      setIsCopied(true)
      setTimeout(() => setIsCopied(false), 2000)
    }
  }

  const alertMsg = props.alertMsg

  if (alertMsg == null || alertMsg === '') {
    return null
  }

  return (
    <Modal
      style={{
        content: {
          // wordWrap: 'break-word',  // 允许长单词换行
          // whiteSpace: 'pre-wrap',  // 保留换行符，合并空白符
          // overflowWrap: 'break-word', // 优先在单词内部换行
          maxHeight: '80vh',
          // margin: 'auto',
          borderRadius: '8px',
          overflow: 'auto',
          // justifyContent: 'center',
          // alignItems: 'center',
          left: '20px',
          right: '20px',
          inset: 'auto',
          maxWidth: '99vw' // 添加最大宽度
        },
        overlay: {
          display: 'flex',
          backgroundColor: 'rgba(0, 0, 0, 0.5)', // 半透明背景
          alignItems: 'center',
          justifyContent: 'center'
        }
      }}
      isOpen={alertMsg !== ''}
      onRequestClose={() => {
        props.onRequestClose?.()
        setIsCopied(false)
      }}
    >
      <div>
        <div style={{
          display: 'flex',
          justifyContent: 'flex-end'
        }}>
          <button
            className="copy"
            onClick={() => copyToClipboard(alertMsg)}
          >
            {isCopied ? '✓ 已复制' : '复制'}
          </button>
        </div>
        <pre
          style={{
            // whiteSpace: 'pre-wrap'
            // wordWrap: 'break-word',
            margin: 0
          }}
        >
            {alertMsg}
          </pre>
      </div>
    </Modal>
  )
}

export default AlertModal
