import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import StorageUtil from '../utils/StorageUtil'

function ActionHistory() {
  const navigate = useNavigate()

  const [list, setList] = useState(
    StorageUtil.getActionHistory()
  )

  const onDelete = (action) => {
    StorageUtil.removeActionHistory(action)

    setList(
      StorageUtil.getActionHistory()
    )
  }

  const onSelect = (item) => {
    navigate('/', { state: item })
  }

  return (
    <div className="App-Content padding-row-10">

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          marginBottom: 16
        }}
      >
        <button
          onClick={() => navigate(-1)}
          style={{
            padding: '8px 12px',
            borderRadius: '6px',
            cursor: 'pointer'
          }}
        >
          ← 返回
        </button>

      </div>

      <h2>Action 历史</h2>

      {
        list.map(item => (
          <div
            key={item.action}
            className="row"
            onClick={() => onSelect(item)}
          >
            <div style={{ flex: 1 }}>
              {item.action}
            </div>

            <button
              onClick={(e) => {
                e.stopPropagation()
                onDelete(item.action)
              }}
            >
              删除
            </button>
          </div>
        ))
      }
    </div>
  )
}

export default ActionHistory
